#!/usr/bin/env python3
"""Genera la comparativa de esta unidad desde las evidencias locales preservadas."""
from pathlib import Path
import json,html,hashlib
root=Path(__file__).resolve().parents[2]/'.local/evidencias/pulido-ui';before=json.loads((root/'antes/auditoria.json').read_text());after=json.loads((root/'despues/auditoria.json').read_text())
assert len(after)==110
assert all(not r['accessibility']['contrast']['failures'] and r['accessibility']['dialogFooterVisible'] and not r['accessibility']['documentOverflow'] for r in after)
metrics={'base':'e46b905','antes':{'estados':len(before),'capturas':len(list((root/'antes').glob('*.png')))},'despues':{'estados':len(after),'capturas':len(list((root/'despues').glob('*.png'))),'textosContrastados':sum(r['accessibility']['contrast']['checked'] for r in after),'fallosContraste':0,'desbordesHorizontales':0,'accionesDialogosFueraPantalla':0},'frontend':{'correctas':107},'backendH2':{'correctas':169,'omitidas':1},'origenFinal':'http://localhost:5174','doblesSoloEnPlaywright':True}
(root/'resumen.json').write_text(json.dumps(metrics,ensure_ascii=False,indent=2))
pairs=[('inicio','Portada institucional'),('privacidad','Aviso de privacidad'),('consulta-{size}-identificacion','Identificación de persona adulta'),('vulneracion-{size}-campos','Vulneración y personas relacionadas'),('adjunto-rechazado','Adjuntos rechazados'),('consulta-{size}-revision','Revisión antes de enviar'),('envio-error','Respuesta incierta y reintento'),('consulta-{size}-recibido','Recepción con registro pendiente'),('nna-{size}-contactos','Contacto seguro NNA'),('nna-{size}-dark','Modo oscuro NNA'),('nna-{size}-texto130','Alto contraste y texto al 130 %')]
sections=[]
for kind,label in pairs:
 for size in ['escritorio','movil']:
  key=kind.format(size=size) if '{size}' in kind else f'{kind}-{size}'+('-light' if kind=='inicio' else '')
  assert (root/'antes'/f'{key}.png').exists(),key
  assert (root/'despues'/f'{key}.png').exists(),key
  figures=''.join(f'<figure><figcaption>{caption}</figcaption><a href="{phase}/{key}.png"><img loading="lazy" src="{phase}/{key}-pantalla.png" alt="{html.escape(label)}: {caption.lower()}, {size}"></a><a class="full" href="{phase}/{key}.png">Ver página completa</a></figure>' for phase,caption in [('antes','Antes'),('despues','Después')])
  sections.append(f'<section data-size="{size}"><h2>{html.escape(label)} <span>{size}</span></h2><div class="pair {size}">{figures}</div></section>')
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparativa UI · Formulario Público</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f8fa;color:#203e4c;font:16px/1.6 Arial,sans-serif}main{max-width:1500px;margin:auto;padding:40px 24px}header{max-width:1000px;margin-bottom:40px}h1{font-size:clamp(28px,4vw,46px);line-height:1.2}h1 b{color:#9e1f63}header p{color:#516873}nav{position:sticky;top:0;z-index:1;background:#fff;border:1px solid #d7e2e7;border-radius:12px;padding:14px 20px;display:flex;gap:14px;align-items:center;box-shadow:0 8px 20px #203e4c0a}select{font:inherit;padding:8px}section{margin:40px 0 60px}h2{font-size:20px}h2 span{font-size:14px;font-weight:400;color:#516873;margin-left:12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.pair.movil{max-width:840px;margin:auto}figure{margin:0;background:white;border:1px solid #d7e2e7;border-radius:12px;overflow:hidden}figcaption{padding:12px 18px;font-weight:bold;border-bottom:3px solid #2fa9d7}figure:nth-child(2) figcaption{border-bottom-color:#9e1f63}img{width:100%;height:auto;display:block}.full{display:block;padding:14px 18px;color:#155e78}a:focus-visible,select:focus-visible{outline:3px solid #155e78;outline-offset:4px}section[hidden]{display:none}@media(max-width:650px){.pair{grid-template-columns:1fr}main{padding:24px 12px}}@media(prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}</style><main><header><p>Defensoría de la Niñez · Evidencia de implementación · 24 de octubre de 2026</p><h1>Una experiencia institucional <b>más clara y cercana.</b></h1><p>Comparación contra el checkpoint e46b905. Datos sintéticos y respuestas controladas en el navegador; estas imágenes no acreditan una recepción institucional real.</p><p>76 estados antes · 110 después · Escritorio 1440 × 1000 · Móvil 390 × 844 y reflujo adicional a 320 px.</p></header><nav><label for="size">Ver capturas</label><select id="size"><option value="todos">Escritorio y móvil</option><option value="escritorio">Escritorio</option><option value="movil">Móvil</option></select><a href="#top">Volver arriba</a></nav><div id="top"></div>'''+''.join(sections)+'''<footer>107 pruebas frontend y 169 backend correctas (una omisión opcional). Consulta el informe y el checkpoint para los alcances de verificación.</footer></main><script>document.querySelector('#size').addEventListener('change',e=>document.querySelectorAll('section').forEach(s=>s.hidden=e.target.value!=='todos'&&s.dataset.size!==e.target.value));</script></html>'''
(root/'comparativa.html').write_text(page)
print('Comparativa guardada:',len(sections),'pares; métricas verificadas.')